import React, { useState } from 'react';
import { AppStep, PaperConfig, Section } from './types';
import InputPhase from './components/InputPhase';
import OutlinePhase from './components/OutlinePhase';
import GenerationPhase from './components/GenerationPhase';
import FinalView from './components/FinalView';
import { generateOutline } from './services/geminiService';

function App() {
  const [step, setStep] = useState<AppStep>(AppStep.INPUT);
  const [config, setConfig] = useState<PaperConfig>({
    title: '',
    tone: 'Formal Academic',
    template: 'Standard Article',
    targetLength: 'Standard Article (8-12 pages)',
    rawSketch: ''
  });
  const [sections, setSections] = useState<Section[]>([]);
  const [isGeneratingOutline, setIsGeneratingOutline] = useState(false);

  const handleConfigChange = (key: keyof PaperConfig, value: any) => {
    setConfig(prev => ({ ...prev, [key]: value }));
  };

  const handleCreateOutline = async () => {
    setIsGeneratingOutline(true);
    try {
      const rawSections = await generateOutline(config);
      const formattedSections: Section[] = rawSections.map(s => ({
        id: crypto.randomUUID(),
        title: s.title,
        description: s.description,
        content: '',
        status: 'PENDING'
      } as Section));

      setSections(formattedSections);
      setStep(AppStep.OUTLINE);
    } catch (error) {
      console.error(error);
      alert("Failed to generate outline. Please try again.");
    } finally {
      setIsGeneratingOutline(false);
    }
  };

  const startGeneration = () => {
    setStep(AppStep.GENERATING);
  };

  const handleRestart = () => {
    if (confirm("This will clear all generated content. Are you sure?")) {
      setStep(AppStep.INPUT);
      setConfig({
        title: '',
        tone: 'Formal Academic',
        template: 'Standard Article',
        targetLength: 'Standard Article (8-12 pages)',
        rawSketch: ''
      });
      setSections([]);
    }
  };

  const handleBackToSketch = () => {
    setStep(AppStep.INPUT);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <div className="fixed inset-0 pointer-events-none z-0 opacity-40">
        <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-b from-indigo-50 to-transparent" />
      </div>

      <div className="relative z-10">
        {step === AppStep.INPUT && (
          <InputPhase 
            config={config} 
            onChange={handleConfigChange} 
            onNext={handleCreateOutline} 
            isGenerating={isGeneratingOutline}
            hasExistingContent={sections.length > 0}
            onContinue={() => setStep(AppStep.OUTLINE)}
          />
        )}

        {step === AppStep.OUTLINE && (
          <OutlinePhase 
            sections={sections} 
            setSections={setSections} 
            onNext={startGeneration}
            onBack={handleBackToSketch}
          />
        )}

        {step === AppStep.GENERATING && (
          <GenerationPhase 
            config={config} 
            sections={sections} 
            setSections={setSections}
            onFinished={() => setStep(AppStep.FINISHED)}
          />
        )}

        {step === AppStep.FINISHED && (
          <FinalView 
            config={config} 
            sections={sections} 
            onRestart={handleRestart}
            onEditSketch={handleBackToSketch}
          />
        )}
      </div>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { PaperConfig, Section } from '../types';
import { Copy, Download, RotateCcw, PenTool } from 'lucide-react';

interface FinalViewProps {
  config: PaperConfig;
  sections: Section[];
  onRestart: () => void;
  onEditSketch: () => void;
}

const FinalView: React.FC<FinalViewProps> = ({ config, sections, onRestart, onEditSketch }) => {
  const [copied, setCopied] = useState(false);

  const fullDocument = `
\\documentclass{article}
\\usepackage[utf8]{inputenc}
\\usepackage{amsmath, amssymb, amsthm}
\\usepackage{graphicx}
\\usepackage{hyperref}

\\title{${config.title}}
\\author{Generated by Research Architect}
\\date{\\today}

\\begin{document}

\\maketitle

${sections.map(s => `% --- Section: ${s.title} ---\n${s.content}`).join('\n\n')}

\\end{document}
  `;

  const handleCopy = () => {
    navigator.clipboard.writeText(fullDocument);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const blob = new Blob([fullDocument], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${config.title.replace(/\s+/g, '_').toLowerCase()}.tex`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen bg-slate-50 p-8 flex flex-col">
      <div className="max-w-6xl mx-auto w-full flex-1 flex flex-col">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
          <div>
            <h1 className="text-3xl font-serif font-bold text-slate-900">Paper Finalized</h1>
            <p className="text-slate-600">Review your full LaTeX assembly below.</p>
          </div>
          <div className="flex flex-wrap gap-3">
             <button 
              onClick={onEditSketch}
              className="flex items-center gap-2 px-4 py-2 text-slate-600 hover:text-indigo-600 font-medium transition-colors"
              title="Go back to your initial notes"
            >
              <PenTool className="w-4 h-4" />
              Edit Sketch
            </button>
             <button 
              onClick={onRestart}
              className="flex items-center gap-2 px-4 py-2 text-slate-500 hover:text-red-600 font-medium transition-colors"
            >
              <RotateCcw className="w-4 h-4" />
              New Paper
            </button>
            <button 
              onClick={handleDownload}
              className="flex items-center gap-2 px-5 py-2.5 border border-slate-300 bg-white hover:bg-slate-50 rounded-lg text-slate-700 font-medium transition-colors"
            >
              <Download className="w-4 h-4" />
              Download .tex
            </button>
            <button 
              onClick={handleCopy}
              className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium shadow-md transition-all min-w-[160px] justify-center"
            >
              {copied ? 'Copied!' : 'Copy to Clipboard'}
              {!copied && <Copy className="w-4 h-4" />}
            </button>
          </div>
        </div>

        <div className="flex-1 bg-[#1e1e1e] rounded-xl shadow-2xl overflow-hidden flex flex-col border border-slate-700">
          <div className="bg-[#2d2d2d] px-4 py-2 flex items-center gap-2 border-b border-black/20">
