import { GoogleGenAI, Type } from "@google/genai";
import { PaperConfig, Section } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const cleanLatex = (text: string) => {
  return text.replace(/```latex/g, '').replace(/```/g, '').trim();
};

export const generateOutline = async (config: PaperConfig): Promise<Array<{ title: string; description: string }>> => {
  const model = "gemini-3-pro-preview"; 

  const prompt = `
    You are an expert academic editor specializing in technical and mathematical fields. 
    I have a sketch for a document of type: "${config.targetLength}".

    **Scope Constraints:**
    - "Dissertation/Book": Generate 15-25 highly detailed sections/sub-sections.
    - "Extended Report": Generate 10-15 logical sections.
    - "Standard Article": Generate 6-10 standard academic sections.
    - "Short Letter": Generate 3-5 concise sections.

    Title: ${config.title}
    Tone: ${config.tone}

    **Instructions:**
    Break the user's notes into these sections. Ensure each section has a 'description' that acts as a directive for the writing agent. 
    If the user mentions specific lemmas, theorems, or data points, ensure they are explicitly assigned to a section.

    Notes:
    ${config.rawSketch}

    Return a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["title", "description"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text);
    }
    throw new Error("No text returned from Gemini");
  } catch (error) {
    console.error("Error generating outline:", error);
    throw error;
  }
};

export const generateSectionContent = async (
  section: Section,
  allSections: Section[],
  config: PaperConfig
): Promise<string> => {
  const model = "gemini-3-pro-preview"; 

  const completedSections = allSections.filter(s => s.status === 'COMPLETED');
  const previousSection = completedSections.length > 0 ? completedSections[completedSections.length - 1] : null;

  // Truncate to avoid context window overflow in 50+ page docs
  const previousContentSnippet = previousSection 
    ? (previousSection.content.length > 3500 
        ? "...(truncated context)...\n" + previousSection.content.slice(-3500) 
        : previousSection.content)
    : "Starting the document.";

  const structureMap = allSections.map(s => `- ${s.title}`).join('\n');

  const prompt = `
    You are a professional researcher and mathematician. 
    Write the LaTeX for section: "${section.title}".

    **Document Context:**
    Full Outline:
    ${structureMap}

    Tone: ${config.tone}
    Style: ${config.template}

    **Writing Directives (from user sketch):**
    ${section.description}

    **Context (Ending of the previous section):**
    ${previousContentSnippet}

    **CRITICAL MATHEMATICIAN WRITING STYLE:**
    1. **Equation Flow:** Do NOT write long paragraphs of text explaining math. Instead, "converge" on results using a sequence of equations. 
       - Use \\begin{align*} or \\begin{align} for derivations.
       - Place equations on separate lines vertically.
       - Each step in a derivation should be clear.
    2. **Avoid "Sketchy" Prose:** Do not use vague terms. Be rigorous. 
    3. **Flesh Out, Don't Invent:** Use the user's core ideas. If they provide a rough note like "prove A = B", perform the formal proof. If they provide a graph description, describe it in technical prose.
    4. **Output Format:** RAW LaTeX only. No preamble, no \\begin{document}. Start directly with \\section{...} or the content of the section.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        thinkingConfig: {
            thinkingBudget: 8192 // High reasoning budget for better math derivations
        }
      }
    });

    return cleanLatex(response.text || "");
  } catch (error) {
    console.error(`Error generating section ${section.title}:`, error);
    throw error;
  }
};

