  template: 'Standard Article' | 'IEEE' | 'ACM' | 'Minimalist';
  targetLength: PaperLength;
  rawSketch: string;
  voiceSample?: string; // Optional field for the model to analyze voice
}

export interface GlobalState {
  step: AppStep;
  config: PaperConfig;
  sections: Section[];
  isGeneratingOutline: boolean;
}

