    2. STRUCTURE: Use standard ${config.discipline} rhetorical patterns (e.g., Literature Review -> Theoretical Framework -> Argument -> Synthesis).
    3. DIRECTIVES: For each section, write a "description" that acts as a strict instruction for a writing agent. Mention exactly which points from the user's notes belong in that section.

    User's Raw Sketch:
    ${config.rawSketch}

    Return a JSON array of objects with {title, description}.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING }
            },
            required: ["title", "description"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text);
    }
    throw new Error("No text returned");
  } catch (error) {
    console.error("Outline error:", error);
    throw error;
  }
};

/**
 * Stage 2: The Rhetorical Mirror
 * Writes the content of a specific section while strictly adhering to 
 * the user's voice and the global logical consistency of the paper.
 */
export const generateSectionContent = async (
  section: Section,
  allSections: Section[],
  config: PaperConfig
): Promise<string> => {
  const model = "gemini-3-pro-preview"; 

  const previousSections = allSections.filter(s => s.status === 'COMPLETED');
  const contextSnippet = previousSections.map(s => `Section: ${s.title}\nContent Snippet: ${s.content.slice(-2000)}`).join('\n\n');

  const prompt = `
    You are a master rhetorician in the field of ${config.discipline}. 
    Write the LaTeX content for: "${section.title}".

    **THE MISSION (MIRRORING OVER MODELLING):**
    Your job is NOT to be a creative writer. Your job is to be a master editor who takes the user's messy notes and transforms them into polished, professional ${config.discipline} prose.

    **VOICE FINGERPRINT:**
    - Rhetorical Mode: ${config.rhetoricalMode}
    - User's Tone: ${config.tone}
    - Voice Sample (MIMIC THIS EXACTLY):
      "${config.voiceSample || "No sample. Use high-end, lucid academic prose appropriate for " + config.discipline}"

    **GLOBAL CONSISTENCY (THE "AUDIT"):**
    - You MUST cross-check your writing against the "Full Truth" (the raw sketch) below.
    - Ensure that the argument in this section aligns perfectly with the premises laid out in the introduction and the logical flow of the entire paper.
    - Do not introduce contradictions or "unearned" conclusions that aren't supported by the user's notes.

    **STYLE GUIDELINES:**
    1. If "Lucid/Empirical (Dawkins-style)": Use short, punchy sentences, clear active verbs, and direct logical links.
    2. If "Dialectic/Continental": Allow for more complex clause structures, reflexive terminology, and conceptual depth.
    3. If "Technical/Formal": Prioritize precision of terminology and standardized reporting.
    4. **LaTeX:** Output RAW LaTeX only. Use \\section{${section.title}} or appropriately leveled headers. Use \\begin{align*} for math if required by the discipline.

    **CONTEXT FOR THIS SECTION:**
    Current Section Directive: ${section.description}
    Full Global Sketch (The Truth):
    ${config.rawSketch}

    **PREVIOUS CONTINUITY:**
    ${contextSnippet || "This is the first section."}
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        thinkingConfig: {
            thinkingBudget: 16000 // Heavy thinking for rhetorical coherence and logic audit
        }
      }
    });

    return cleanLatex(response.text || "");
  } catch (error) {
    console.error(`Generation error:`, error);
    throw error;
  }
};

export enum AppStep {
  INPUT = 'INPUT',
  OUTLINE = 'OUTLINE',
  GENERATING = 'GENERATING',
  FINISHED = 'FINISHED'
}

export enum SectionStatus {
  PENDING = 'PENDING',
  GENERATING = 'GENERATING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface Section {
  id: string;
  title: string;
  description: string;
  content: string;
  status: SectionStatus;
  originalContent?: string; // Used in Import Mode to preserve existing prose
}

export type PaperLength = 'Short Letter (2-4 pages)' | 'Standard Article (8-12 pages)' | 'Extended Report (20-30 pages)' | 'Dissertation/Book (40+ pages)';

export type Discipline = 'Philosophy' | 'Psychology' | 'Mathematics/Physics' | 'Computer Science' | 'General/Interdisciplinary';
export type RhetoricalMode = 'Lucid/Empirical (Dawkins-style)' | 'Dialectic/Continental' | 'Technical/Formal' | 'Minimalist';

export interface PaperConfig {
  title: string;
  tone: 'Formal Academic' | 'Casual/Blog' | 'Technical Report';
  discipline: Discipline;
  rhetoricalMode: RhetoricalMode;
  template: 'Standard Article' | 'IEEE' | 'ACM' | 'Minimalist';
  targetLength: PaperLength;
  rawSketch: string;
  voiceSample?: string;
  // New Quant/Import features
  quantMode: boolean;
  importMode: boolean;
  existingPaperContent?: string;
}

export interface GlobalState {
  step: AppStep;
  config: PaperConfig;
  sections: Section[];
  isGeneratingOutline: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { PaperConfig, Section } from "../types";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

const cleanLatex = (text: string) => {
  return text.replace(/```latex/g, '').replace(/```/g, '').trim();
};

/**
 * Stage 1: The Logical Architect
 * Analyzes the raw notes OR existing paper and builds a structure.
 */
export const generateOutline = async (config: PaperConfig): Promise<Array<{ title: string; description: string; content?: string }>> => {
  const model = "gemini-3-pro-preview"; 

  const prompt = config.importMode 
    ? `
    You are a Research Ingestion Agent. 
    Task: Parse the provided LaTeX research paper. Extract the sections accurately.

    **Instructions:**
    1. Identify all \section and \subsection blocks.
    2. For each block, return the 'title' and the full 'content' (the LaTeX text inside that section).
    3. Provide a brief 'description' of what that section currently contains.

    Existing Paper:
    ${config.existingPaperContent}

    Return a JSON array of objects with {title, description, content}.
    `
    : `
    You are a Structural Architect for ${config.discipline} research.
    Your goal is to reorganize a messy "sketch" of notes into a logical, coherent outline for a "${config.targetLength}".

    **Instructions:**
    1. READ carefully: Do not invent new knowledge. Identify the core thesis and sub-arguments in the sketch.
    2. STRUCTURE: Use standard ${config.discipline} rhetorical patterns.
    3. DIRECTIVES: For each section, write a "description" that acts as a strict instruction for a writing agent.

    User's Raw Sketch:
    ${config.rawSketch}

    Return a JSON array of objects with {title, description}.
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              content: { type: Type.STRING, description: "Only present if in import mode." }
            },
            required: ["title", "description"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text);
    }
    throw new Error("No text returned");
  } catch (error) {
    console.error("Outline error:", error);
    throw error;
  }
};

/**
 * Stage 2: The Rhetorical Mirror + Quant Expansion
 */
export const generateSectionContent = async (
  section: Section,
  allSections: Section[],
  config: PaperConfig
): Promise<string> => {
  const model = "gemini-3-pro-preview"; 

  const previousSections = allSections.filter(s => s.status === 'COMPLETED');
  const contextSnippet = previousSections.map(s => `Section: ${s.title}\nContent Snippet: ${s.content.slice(-2000)}`).join('\n\n');

  // If in quant mode, we add the google search tool and modify instructions
  const isQuant = config.quantMode;

  const prompt = `
    You are a master rhetorician ${isQuant ? 'and Quantitative Researcher' : ''} in the field of ${config.discipline}. 
    Task: ${section.content ? 'EXPAND and QUANTIFY' : 'Write'} the LaTeX content for: "${section.title}".

    ${section.content ? `
    **IMPORT MODE DIRECTIVE:**
    The following LaTeX already exists for this section:
    """
    ${section.content}
    """
    1. **DO NOT CHANGE THE ORIGINAL PROSE.** It is already polished.
    2. Your task is to IDENTIFY equations, algorithms, or logical claims.
    3. ${isQuant ? 'Use Google Search to find REAL-TIME data for any variables (e.g., current statistics, rates, constants).' : 'Polish the transitions.'}
    4. APPEND a new block after the relevant equations titled "Empirical Grounding" or "Worked Case Study".
    5. In this new block, show the calculation using the real-time data you found.
    6. If an algorithm is present, write a "Simulation Snippet" or Python block that demonstrates its logic with representative data.
    ` : `
    **WRITING MODE DIRECTIVE:**
    1. Use the User's Sketch to write this section from scratch.
    2. ${isQuant ? 'Whenever you use a variable or equation, use Google Search to ground it in real 2024/2025 data.' : ''}
    `}

    **VOICE FINGERPRINT:**
    - Rhetorical Mode: ${config.rhetoricalMode}
    - User's Tone: ${config.tone}
    - Voice Sample: "${config.voiceSample || "Standard high-end academic."}"

    **STYLE GUIDELINES:**
    - Output RAW LaTeX only.
    - If you perform a simulation (Monte Carlo, etc.), describe the methodology and result based on the real-time data parameters.

    **CONTEXT:**
    Current Section Directive: ${section.description}
    Full Global Sketch/Truth: ${config.rawSketch || "See imported content."}

    **PREVIOUS CONTINUITY:**
    ${contextSnippet || "This is the first section."}
  `;

  try {
    const response = await ai.models.generateContent({
      model,
      contents: prompt,
      config: {
        tools: isQuant ? [{ googleSearch: {} }] : undefined,
        thinkingConfig: {
            thinkingBudget: 16000 
        }
      }
    });

    let result = cleanLatex(response.text || "");

    // If we were just expanding, we ensure we return the FULL section (original + expansion)
    // unless the AI only returned the expansion. If it returned only expansion, we merge.
    if (section.content && !result.includes(section.content.slice(0, 50))) {
        return section.content + "\n\n" + result;
    }

    return result;
  } catch (error) {
    console.error(`Generation error:`, error);
    throw error;
  }
};

import React, { useState } from 'react';
import { AppStep, PaperConfig, Section, SectionStatus } from './types';
import InputPhase from './components/InputPhase';
import OutlinePhase from './components/OutlinePhase';
import GenerationPhase from './components/GenerationPhase';
import FinalView from './components/FinalView';
import { generateOutline } from './services/geminiService';

function App() {
  const [step, setStep] = useState<AppStep>(AppStep.INPUT);
  const [config, setConfig] = useState<PaperConfig>({
    title: '',
    tone: 'Formal Academic',
    discipline: 'Philosophy',
    rhetoricalMode: 'Lucid/Empirical (Dawkins-style)',
    template: 'Standard Article',
    targetLength: 'Standard Article (8-12 pages)',
    rawSketch: '',
    voiceSample: '',
    quantMode: false,
    importMode: false,
    existingPaperContent: ''
  });
  const [sections, setSections] = useState<Section[]>([]);
  const [isGeneratingOutline, setIsGeneratingOutline] = useState(false);

  const handleConfigChange = (key: keyof PaperConfig, value: any) => {
    setConfig(prev => ({ ...prev, [key]: value }));
  };

  const handleCreateOutline = async () => {
    setIsGeneratingOutline(true);
    try {
      const rawSections = await generateOutline(config);
      const formattedSections: Section[] = rawSections.map(s => ({
        id: crypto.randomUUID(),
        title: s.title,
        description: s.description,
        content: s.content || '', // In import mode, content will be populated
        status: SectionStatus.PENDING
      } as Section));

      setSections(formattedSections);
      setStep(AppStep.OUTLINE);
    } catch (error) {
      console.error(error);
      alert("Failed to generate outline or parse paper. Please check your connection and try again.");
    } finally {
      setIsGeneratingOutline(false);
    }
  };

  const startGeneration = () => {
    setStep(AppStep.GENERATING);
  };

  const handleRestart = () => {
    if (confirm("This will clear all generated content. Are you sure?")) {
      setStep(AppStep.INPUT);
      setConfig({
        title: '',
        tone: 'Formal Academic',
        discipline: 'Philosophy',
        rhetoricalMode: 'Lucid/Empirical (Dawkins-style)',
        template: 'Standard Article',
        targetLength: 'Standard Article (8-12 pages)',
        rawSketch: '',
        voiceSample: '',
        quantMode: false,
        importMode: false,
        existingPaperContent: ''
      });
      setSections([]);
    }
  };

  const handleBackToSketch = () => {
    setStep(AppStep.INPUT);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">
      <div className="fixed inset-0 pointer-events-none z-0 opacity-40">
        <div className="absolute top-0 left-0 w-full h-96 bg-gradient-to-b from-indigo-50 to-transparent" />
      </div>

      <div className="relative z-10">
        {step === AppStep.INPUT && (
          <InputPhase 
            config={config} 
            onChange={handleConfigChange} 
            onNext={handleCreateOutline} 
            isGenerating={isGeneratingOutline}
            hasExistingContent={sections.length > 0}
            onContinue={() => setStep(AppStep.OUTLINE)}
          />
        )}

        {step === AppStep.OUTLINE && (
          <OutlinePhase 
            sections={sections} 
            setSections={setSections} 
            onNext={startGeneration}
            onBack={handleBackToSketch}
          />
        )}

        {step === AppStep.GENERATING && (
          <GenerationPhase 
            config={config} 
            sections={sections} 
            setSections={setSections}
            onFinished={() => setStep(AppStep.FINISHED)}
          />
        )}

        {step === AppStep.FINISHED && (
          <FinalView 
            config={config} 
            sections={sections} 
            onRestart={handleRestart}
            onEditSketch={handleBackToSketch}
          />
        )}
      </div>
    </div>
  );
}

export default App;
